CREATE TABLE IF NOT EXISTS holidays (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), holiday_date DATE UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, optional BOOLEAN NOT NULL DEFAULT FALSE, created_by UUID REFERENCES users(id));
CREATE TABLE IF NOT EXISTS attendance_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE, attendance_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PRESENT', check_in TIMESTAMPTZ, check_out TIMESTAMPTZ, overtime_hours NUMERIC(6,2) DEFAULT 0, remarks VARCHAR(500), created_by UUID REFERENCES users(id), UNIQUE(employee_id,attendance_date));
CREATE TABLE IF NOT EXISTS leave_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE, leave_type VARCHAR(40) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, days NUMERIC(6,2) NOT NULL, reason VARCHAR(500), status VARCHAR(20) NOT NULL DEFAULT 'PENDING', approved_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payroll_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_month DATE NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', total_gross NUMERIC(15,2) NOT NULL DEFAULT 0, total_deductions NUMERIC(15,2) NOT NULL DEFAULT 0, total_net NUMERIC(15,2) NOT NULL DEFAULT 0, finalized_by UUID REFERENCES users(id), finalized_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS payroll_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payroll_run_id UUID NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE, employee_id UUID NOT NULL REFERENCES employees(id), basic_salary NUMERIC(15,2) NOT NULL DEFAULT 0, hra NUMERIC(15,2) NOT NULL DEFAULT 0, incentives NUMERIC(15,2) NOT NULL DEFAULT 0, commission NUMERIC(15,2) NOT NULL DEFAULT 0, bonus NUMERIC(15,2) NOT NULL DEFAULT 0, pf NUMERIC(15,2) NOT NULL DEFAULT 0, esic NUMERIC(15,2) NOT NULL DEFAULT 0, professional_tax NUMERIC(15,2) NOT NULL DEFAULT 0, loan_recovery NUMERIC(15,2) NOT NULL DEFAULT 0, gross_salary NUMERIC(15,2) NOT NULL DEFAULT 0, total_deductions NUMERIC(15,2) NOT NULL DEFAULT 0, net_salary NUMERIC(15,2) NOT NULL DEFAULT 0, payment_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', payment_date DATE, payment_mode VARCHAR(30), UNIQUE(payroll_run_id,employee_id));
